ValidationRule.errorConditionFormula:
AND(
    ISCHANGED(Status__c),

    OR(

        /* Criado não pode ir direto para Em rota ou Entregue */
        AND(
            TEXT(PRIORVALUE(Status__c)) = "Criado",
            OR(
                ISPICKVAL(Status__c, "Em rota"),
                ISPICKVAL(Status__c, "Entregue")
            )
        ),

        /* Em preparação não pode ir direto para Entregue */
        AND(
            TEXT(PRIORVALUE(Status__c)) = "Em preparação",
            ISPICKVAL(Status__c, "Entregue")
        ),

        /* Entregue não pode mudar */
        TEXT(PRIORVALUE(Status__c)) = "Entregue",

        /* Cancelado não pode mudar */
        TEXT(PRIORVALUE(Status__c)) = "Cancelado"

    )
)
